change.sales.py:
"""Small helpers for daily sales figures."""


def total(values):
    """Sum of all values."""
    return sum(values)


def total_between(values, start, end):
    """Sum of values[start] through values[end], both ends included."""
    result = 0
    for i in range(start, end):
        result += values[i]
    return result
